$rel='param\gameparam\gameparam.parambnd.dcx';$b=[SoulsFormats.BND4]::Read((Raw (Join-Path $clean $rel)));$n=[SoulsFormats.BND4]::Read((Raw (Join-Path $mods $rel)));$l=[SoulsFormats.BND4]::Read((Raw (Join-Path $lw $rel)))
$byType=@{};foreach($df in Get-ChildItem -LiteralPath $defs -Filter '*.xml'){$xml=[xml](Get-Content -LiteralPath $df.FullName -Raw);$byType[[string]$xml.PARAMDEF.ParamType]=$df.BaseName}
$groups=@{};foreach($g in $plan.changes|Group-Object table){$groups[$g.Name]=$g.Group}
function RowMap($table){$seen=@{};$map=@{};$keys=@();foreach($r in $table.Rows){$id=[string]$r.ID;$count=$seen[$id];if($null -eq $count){$count=0};$seen[$id]=$count+1;$key=$id+'#'+$count;$map[$key]=$r;$keys+=$key};@{map=$map;keys=$keys}}
$changedTables=@();$rowsChecked=0;$cellsChecked=0
foreach($f in $b.Files){
 $name=[IO.Path]::GetFileName($f.Name);$table=$name -replace '\.param$','';$nf=Member $n $name
 if(-not $groups.ContainsKey($table)){Need ([Convert]::ToHexString($f.Bytes.ToArray()) -ceq [Convert]::ToHexString($nf.Bytes.ToArray())) "Unrelated binder member changed $table";continue}
 $temp=[SoulsFormats.PARAM]::Read($f.Bytes);$def=$byType[[string]$temp.ParamType];$bt=Table $b $table $def;$nt=Table $n $table $def;$lt=Table $l $table $def;$bm=RowMap $bt;$nm=RowMap $nt;$lm=RowMap $lt;$edits=@{};foreach($r in $groups[$table]){$edits[$r.key]=$r};$new=@($groups[$table]|Where-Object new).Count
 Need ($nt.Rows.Count -eq $bt.Rows.Count+$new) "Unexpected row count $table"
 foreach($key in $bm.keys){$r=$bm.map[$key];$actual=$nm.map[$key];Need ($null -ne $actual) 'Original row removed';$edit=$edits[$key]
  if($null -eq $edit){Need ((Sig $r) -ceq (Sig $actual)) "Unrelated row changed $table/$key"}else{$allow=@{};foreach($c in $edit.cells){$allow[$c.field]=$true};foreach($c in $r.Cells){$av=(Cell $actual $c.Def.InternalName).Value;$expected=if($allow.ContainsKey($c.Def.InternalName)){(Cell $lm.map[$key] $c.Def.InternalName).Value}else{$c.Value};Need ([string]$expected -ceq [string]$av) "Unexpected cell $table/$key/$($c.Def.InternalName) expected=[$expected] actual=[$av]";$cellsChecked++}};$rowsChecked++
 }
 foreach($entry in $groups[$table]|Where-Object new){Need ((Sig $nm.map[$entry.key]) -ceq (Sig $lm.map[$entry.key])) "New author row mismatch $table/$($entry.key)"}
 $changedTables+=$table
}

$sp=Table $n 'SpEffectParam' 'SpEffect';$durations=@();foreach($id in @(51413,51414)){$v=(Cell (Row $sp $id) 'effectEndurance').Value;Need ($v -eq 24) "Old60s patch leaked $id";$durations+=@{id=$id;seconds=$v}}
