# Verify complete FXR/texture union by names, keeping all non-overridden original NOOB resources.
$rel='sfx\sfxbnd_commoneffects.ffxbnd.dcx';$sourceNoob='E:\PRACA AI CAŁY FOLDER\INNER DOJO\Working\2026-10-24\CLEAN_NOOB_MAIN_PACKAGE\input\mods';$orig=[SoulsFormats.BND4]::Read((Raw (Join-Path $sourceNoob $rel)));$out=[SoulsFormats.BND4]::Read((Raw (Join-Path $mods $rel)));$actual=@{};foreach($f in $out.Files){$key=[IO.Path]::GetFileName($f.Name);if(-not $actual.ContainsKey($key)){$actual[$key]=[Collections.Generic.List[object]]::new()};$actual[$key].Add($f)};$edits=@{};foreach($x in $report.sfxChanges){$edits[$x.name]=$x.sha256};function FH($f){[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($f.Bytes.ToArray()))};$sourceCounts=@{};foreach($f in $orig.Files){$key=[IO.Path]::GetFileName($f.Name);$sourceCounts[$key]++;Need ($actual.ContainsKey($key)) "Original SFX removed $key";$want=if($edits.ContainsKey($key)){$edits[$key]}else{FH $f};foreach($af in $actual[$key]){Need ((FH $af) -ceq $want) "SFX mismatch $key"}};foreach($key in $sourceCounts.Keys){Need ($actual[$key].Count -eq $sourceCounts[$key]) "Original duplicate count changed $key"};foreach($key in $edits.Keys){foreach($af in $actual[$key]){Need ((FH $af) -ceq $edits[$key]) 'Author SFX mismatch'}}

# Verify author and pre-existing Dojo FMG entries, preserving all other entries.
foreach($rel in @('msg\engus\item.msgbnd.dcx','msg\engus\menu.msgbnd.dcx')){$base=[SoulsFormats.BND4]::Read((Raw (Join-Path $clean $rel)));$out=[SoulsFormats.BND4]::Read((Raw (Join-Path $mods $rel)));foreach($f in $base.Files){$name=[IO.Path]::GetFileName($f.Name);$of=Member $out $name;$changes=@{};foreach($c in $report.msgChanges|Where-Object {$_.file -eq $rel -and $_.member -eq $name}){$changes[[int]$c.id]=$c.text};if(-not $changes.Count){Need ([Convert]::ToHexString($f.Bytes.ToArray()) -ceq [Convert]::ToHexString($of.Bytes.ToArray())) 'Unexpected text member change';continue};$bf=[SoulsFormats.FMG]::Read($f.Bytes);$ofm=[SoulsFormats.FMG]::Read($of.Bytes);$om=@{};foreach($e in $ofm.Entries){$om[$e.ID]=$e.Text};foreach($e in $bf.Entries){$want=if($changes.ContainsKey($e.ID)){$changes[$e.ID]}else{$e.Text};Need ([string]$om[$e.ID] -ceq [string]$want) "Unrelated text changed $name/$($e.ID)"};foreach($id in $changes.Keys){Need ([string]$om[$id] -ceq [string]$changes[$id]) 'Author text missing'}}}
Json-Write @{status='STATIC_READBACK_PASS';runtime='NOT_TESTED_IN_GAME';paramChangedTables=$changedTables;existingParamRowsChecked=$rowsChecked;existingEditedRowCellsChecked=$cellsChecked;newRows=$report.paramNewRows;editedCells=$report.paramEditedCells;butterflyDurations=$durations;privateNpcRowAbsent=$true;privateWellActorAbsent=$true;privateActivationEventAbsent=$true;otherDojoFilesUnchanged=$unchangedFiles;originalSfxRetained=$true;authorSfxVerified=$true;authorAndDojoTextsVerified=$true;gameWritten=$false} (Join-Path $taskRoot 'reports\FINAL_READBACK.json')
